def minper(s):
    W=len(s); 
    for p in range(1,W+1):
        if all(s[i]==s[(i+p)%W] for i in range(W)): return p
    return W
def ext(g):
    return [[(g[r][c % W]) if False else g[r][c%W] for c in range(2*W)] for r in g]
# but must use true period p, not W: out[c]=s[c%p]? no — period p means s repeats every p, so out[c]=s[c%p] only if consistent; safer: out = s repeated ceil(2W/p) times truncated
def ext2(g):
    res=[]
    for s in g:
        p=minper(s)
        res.append([s[c%p] for c in range(2*len(s))])
    return res
